/*
 * Zephyr RTOS SPI Loopback Test Application
 */

#include <zephyr/kernel.h>
#include <zephyr/device.h>
#include <zephyr/drivers/spi.h>
#include <string.h>

int main(void)
{
	const struct device *spi_dev;
	int ret;

	/* Get the SPI device */
	spi_dev = DEVICE_DT_GET(DT_NODELABEL(spi0));

	/* Verify the device is initialized and ready */
	if (!device_is_ready(spi_dev)) {
		printk("SPI device is not ready\n");
		return -1;
	}

	/* Define transmit buffer with known pattern */
	uint8_t tx_buffer[8] = {0x01, 0x02, 0x03, 0x04, 0x05, 0x06, 0x07, 0x08};

	/* Define receive buffer initialized to zero */
	uint8_t rx_buffer[8] = {0};

	/* Configure SPI */
	struct spi_config spi_cfg = {
		.frequency = 1000000,
		.operation = SPI_OP_MODE_MASTER | SPI_WORD_SET(8),
		.slave = 0,
		.cs = NULL,
	};

	/* Set up transmit buffer structure */
	struct spi_buf tx_buf = {
		.buf = tx_buffer,
		.len = 8,
	};

	/* Set up receive buffer structure */
	struct spi_buf rx_buf = {
		.buf = rx_buffer,
		.len = 8,
	};

	/* Set up transmit buffer set */
	struct spi_buf_set tx_bufs = {
		.buffers = &tx_buf,
		.count = 1,
	};

	/* Set up receive buffer set */
	struct spi_buf_set rx_bufs = {
		.buffers = &rx_buf,
		.count = 1,
	};

	/* Perform SPI transceive */
	ret = spi_transceive(spi_dev, &spi_cfg, &tx_bufs, &rx_bufs);

	/* Check return value for errors */
	if (ret != 0) {
		printk("SPI transceive failed with error: %d\n", ret);
		return ret;
	}

	/* Compare transmit and receive buffers byte-by-byte */
	if (memcmp(tx_buffer, rx_buffer, 8) == 0) {
		printk("SPI loopback successful\n");
	} else {
		printk("SPI loopback mismatch\n");
		return -1;
	}

	return 0;
}
